Data.Script:
var o = {};
try { o = JSON.parse((vars.dt_el && vars.dt_el.Object) || "{}"); } catch (e) {}
var cardId = (o.tokenData && o.tokenData.cardId) || o.cardId || "";
return {
  dt_parent: cardId ? String(cardId) : String(vars.target.id),
  dt_prop: cardId ? "hp" : "bar1_value",
  dt_name: o.name || vars.target.name || "token"
};

var cur = parseInt(vars.dt_hp, 10);
var dmg = Number(vars.damage) || 0;
if (isNaN(cur)) return { dt_has: 0, dt_text: vars.dt_name + " has no HP to lower." };
var now = Math.max(0, cur - dmg);
return { dt_has: 1, dt_new: String(now), dt_text: vars.dt_name + ": -" + dmg + " HP (" + cur + " -> " + now + ")" };
